// Shared free-text export sanitizer. Browser copy is generated by sync-dashboard.
function sanitizeFreeText(value) {
 if(value==null)return value;
 return String(value)
  .replace(/“[^”]*”|"[^"]*"|(?<!\w)‘[^’]*’(?!\w)|(?<!\w)'[^']*'(?!\w)/g,'')
  .replace(/\b[A-Z0-9._%+-]+\s*(?:\bat\b|\[at\]|\(at\))\s*[A-Z0-9-]+(?:(?:\.|\s*(?:\[dot\]|\(dot\)|\bdot\b)\s*)[A-Z0-9-]+)*(?:\.|\s*(?:\[dot\]|\(dot\)|\bdot\b)\s*)[A-Z]{2,63}\b/gi,'')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'')
  .replace(/\b(?:https?:\/\/|www\.)[^\s<>"']+/gi,'')
  .replace(/\b(?:[A-Z0-9-]+\.)+(?:com|org|net|edu|gov|mil|io|co|mx|uk|ca|us|agency|info|biz|app|dev|ai|me|travel|realty|estate)\b(?:\/[^\s<>"']*)?|\b(?:[A-Z0-9-]+\.)+[A-Z]{2,63}\/[^\s<>"']*/gi,'')
  .replace(/@[A-Z0-9_.-]+/gi,'')
  .replace(/\b(?:account|acct|routing|iban|clabe)(?:\s+(?:number|no\.?))?\s*[:#=-]?\s*(?:[A-Z]{0,4}\d[A-Z0-9]*(?:[ -]+[A-Z0-9]*\d[A-Z0-9]*)*)/gi,match=>{const number=match.replace(/^.*?(?=[A-Z]{0,4}\d)/i,'');return (number.match(/\d/g)||[]).length>=4 || /[A-Z]/i.test(number)&&number.replace(/[^A-Z0-9]/gi,'').length>=6 ? '' : match;})
  .replace(/\+\d[\d\s().-]{6,}\d|\(?\d{3}\)?[ .-]?\d{3}[ .-]?\d{4}|\b\d{10,18}\b/g,'')
  .replace(/\s+/g,' ').trim();
}
function sanitizeReportSnapshot(snapshot){
 const fields={Interactions:['summary','next_step'],Partners:['relationship','commission_exceptions'],Pipeline:['next_step'],Review:['question']};
 return {...snapshot,tabs:Object.fromEntries(Object.entries(snapshot.tabs||{}).map(([tab,rows])=>[tab,Array.isArray(rows)?rows.map(row=>Object.fromEntries(Object.entries(row).map(([key,value])=>[key,(fields[tab]||[]).includes(key)?sanitizeFreeText(value):value]))):rows]))};
}
if(typeof module !== 'undefined') module.exports={sanitizeFreeText,sanitizeReportSnapshot};
